          "하루 빵 수량을 Qd=100−10P, Qs=20+10P라 하자. $3에서는 수요 70·공급 50으로 부족 20이 경쟁 입찰이나 가격 상승을 유도한다. $5에서는 공급 70·수요 50으로 잉여 20이 가격 인하를 유도한다. $4에서는 양쪽 모두 60을 계획하므로 이런 압력이 없다.",
          "가격은 상대 희소성과 잠재 이윤을 알리고 생산 확대나 사용 절약의 유인을 주며 살 의사와 능력이 있는 사람에게 재화를 배분한다. 지출이 향하는 활동으로 자원을 이동시키지만 구매력을 반영하므로 공정성을 보장하지 않는다. 공급 일정 시 수요 증가는 보통 균형가격과 수량을 높이고 공급 증가는 가격을 낮추고 수량을 늘린다."
