          "Allocative efficiency에는 marginal social benefit=marginal social cost가 필요해 마지막 단위의 편익과 자원비용이 같다. 그보다 적으면 추가 단위의 편익이 비용보다 크고 많으면 비용이 편익보다 크다. 경쟁균형이 이를 달성하려면 외부성 부재와 관련 정보 같은 가정이 필요하며 소득 평등을 뜻하지 않는다."
