          "Utility maximization은 감당 가능한 묶음 중 가장 선호하는 것을 고르는 것이지 재화 개수를 최대화하는 것이 아니다. 단순 모형은 일관된 선호와 비교에 충분한 정보를 가정한다. Bounded rationality는 시간·인지 한계로 전면 비교를 못함을, bounded self-control은 의도와 실제 저축의 차이를, bounded selfishness는 타인 배려를 설명한다.",
          "‘중간 가격 선택’ 같은 경험법칙은 노력을 줄이지만 오도할 수 있다. Anchoring은 임의의 첫 가격이 이후 판단에 영향을 주는 것이다. Framing은 같은 확률인 ‘90% 생존’과 ‘10% 사망’에 반응이 달라지는 것이다. Availability bias는 생생한 최근 사고를 덜 기억나는 통계보다 중시하는 것이다. 서로 다른 원리이므로 결정의 어느 특징이 바뀌었는지 밝혀라."
