          "Price elasticity of demand(PED)는 수요량 변화율÷가격 변화율이다. 보통 음수인 것은 역관계를 나타내며 절댓값을 1과 비교한다. 1보다 크면 탄력적, 작으면 비탄력적, 같으면 단위탄력적이다. 대체재·시간·필수성·소득 중 지출 비중이 반응에 영향을 준다.",
          "기준을 일관되게 쓰라. 여기의 초기값 방식은 변화율=(새값−옛값)/옛값×100이다. $10→$11은 10%, 100→80은 −20%로 PED=−2이다. 이 구간에서 가격 1% 상승에 약 2% 수량 감소가 대응하며 두 단위 감소라는 뜻은 아니다.",
