          "비용측 도표는 세로축에 단위당 비용·편익, 가로축에 기간당 생산량을 둔다. 음의 생산외부성은 MSC를 MPC 위에 두며 MSB=MPB일 때 사적 교점이 사회적 교점 오른쪽이다. 음의 소비외부성은 MSB를 MPB 아래에 두고 MSC=MPC이다. 양의 생산은 MSC<MPC, 양의 소비는 MSB>MPB로 사적 생산량이 사회적 최적보다 적다. "
