          "Public good은 이런 특성이지 정부 소유나 바람직함을 뜻하지 않는다. 공공병원 병상은 사용 중 경합적이고 유료도로는 미지불자를 배제한다. 공동어장은 물고기가 경합적이므로 순수 공공재와 다르다. 혼잡은 원래 비경합적 서비스를 일부 구간에서 경합적으로 만들 수 있다.",
          "정부는 세금으로 재원을 마련해 직접 운영하거나 민간에 위탁한다. 위탁은 전문성과 비용경쟁을 가져오지만 품질감시·서비스 의무 설정·경쟁약화 방지가 어렵다. 직접 제공은 보편적 접근을 돕지만 예산·유인 문제가 있다. 소유형태가 자동으로 효율적이라 가정하지 말고 품질과 책임성을 비교하라."
